import math
from fractions import Fraction

def solve(kind, nums):
    if kind == "distance":
        x1, y1, x2, y2 = nums[0], nums[1], nums[2], nums[3]
        d2 = (x2 - x1) ** 2 + (y2 - y1) ** 2
        print(f"  across {x2 - x1}, up {y2 - y1}: d^2 = {(x2 - x1) ** 2} + {(y2 - y1) ** 2} = {d2}")
        if math.isqrt(d2) ** 2 == d2:
            print(f"  d = {math.isqrt(d2)}")
        else:
            print(f"  d = sqrt({d2}), about {math.sqrt(d2):.4f}")
    elif kind == "slope":
        x1, y1, x2, y2 = nums[0], nums[1], nums[2], nums[3]
        if x2 == x1:
            print("  the run is 0: a vertical line, with no slope")
        else:
            print(f"  rise {y2 - y1} over run {x2 - x1}: m = {Fraction(y2 - y1, x2 - x1)}")
    elif kind == "midpoint":
        x1, y1, x2, y2 = nums[0], nums[1], nums[2], nums[3]
        print(f"  average each coordinate: ({Fraction(x1 + x2, 2)}, {Fraction(y1 + y2, 2)})")
    elif kind == "vertex":
        a, b, c = nums[0], nums[1], nums[2]
        h = Fraction(-b, 2 * a)
        k = a * h * h + b * h + c
        print(f"  h = -b/(2a) = {h}, k = f({h}) = {k}")
        if a > 0:
            print(f"  a > 0, so it opens up: ({h}, {k}) is the minimum")
        else:
            print(f"  a < 0, so it opens down: ({h}, {k}) is the maximum")
    elif kind == "ends":
        n, a = nums[0], nums[1]
        print(f"  leading term {a}x^{n}: degree {n}, leading coefficient {a}")
        if n == 0:
            print("  flat on both ends")
        elif n % 2 == 0:
            print(f"  even degree: both ends {'up' if a > 0 else 'down'}")
        elif a > 0:
            print("  odd degree, positive: down on the left, up on the right")
        else:
            print("  odd degree, negative: up on the left, down on the right")
    elif kind == "floor":
        p, q = nums[0], nums[1]
        x = Fraction(p, q)
        print(f"  x = {x}: floor {p // q}, since {p // q} <= {x} < {p // q + 1}")
        print(f"  ceiling {-(-p // q)}, since {-(-p // q) - 1} < {x} <= {-(-p // q)}")

problems = [
    ("Example 2 · (-1, 2) to (5, 10)", "distance", [-1, 2, 5, 10]),
