import math
from fractions import Fraction

def solve(kind, nums):
    if kind == "distance" or kind == "slope" or kind == "midpoint":
        x1, y1, x2, y2 = nums[0], nums[1], nums[2], nums[3]
        d2 = (x2 - x1) ** 2 + (y2 - y1) ** 2
        if kind == "distance" and math.isqrt(d2) ** 2 == d2:
            return f"distance: d = {math.isqrt(d2)}"
        if kind == "distance":
            return f"distance: d = sqrt({d2})"
        if kind == "slope" and x2 == x1:
            return "slope: vertical"
        if kind == "slope":
            return f"slope: m = {Fraction(y2 - y1, x2 - x1)}"
        return f"midpoint: ({Fraction(x1 + x2, 2)}, {Fraction(y1 + y2, 2)})"
    if kind == "vertex":
        a, b, c = nums[0], nums[1], nums[2]
        h = Fraction(-b, 2 * a)
        k = a * h * h + b * h + c
        if a > 0:
            return f"vertex: ({h}, {k}), minimum"
        return f"vertex: ({h}, {k}), maximum"
    if kind == "ends":
        n, a = nums[0], nums[1]
        if n == 0:
            return "ends: flat on both ends"
        if n % 2 == 0 and a > 0:
            return "ends: up on the left, up on the right"
        if n % 2 == 0:
            return "ends: down on the left, down on the right"
        if a > 0:
            return "ends: down on the left, up on the right"
        return "ends: up on the left, down on the right"
    p, q = nums[0], nums[1]
    return f"floor: floor {p // q}, ceiling {-(-p // q)}"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

