from fractions import Fraction

def divide(coeffs, c):
    # synthetic division by x - c, coefficients highest power first: quotient, remainder
    q = []
    carry = 0
    for i in range(len(coeffs)):
        carry = carry * c + coeffs[i]
        if i < len(coeffs) - 1:
            q.append(carry)
    return q, carry

def solve(kind, nums):
    if kind == "line":
        x1, y1, x2, y2, x = nums[0], nums[1], nums[2], nums[3], nums[4]
        m = Fraction(y2 - y1, x2 - x1)
        b = y1 - m * x1
        print(f"  m = {m}, b = y1 - m x1 = {b}, so y = ({m})x + ({b})")
        print(f"  at x = {x}: y = {m * x + b}")
    elif kind == "perp":
        m, x0, y0 = Fraction(nums[0], nums[1]), nums[2], nums[3]
        if m == 0:
            print(f"  slope 0 is horizontal, so the perpendicular is vertical: x = {x0}")
        else:
            p = -1 / m
            print(f"  the negative reciprocal of {m} is {p}, and {m} * ({p}) = {m * p}")
            print(f"  through ({x0}, {y0}): y = ({p})x + ({y0 - p * x0})")
    elif kind == "multiplicity":
        c, coeffs, count = nums[0], [], 0
        for k in range(1, len(nums)):
            coeffs.append(nums[k])
        q, r = divide(coeffs, c)
        while r == 0:
            count = count + 1
            print(f"  divide by x - ({c}): quotient {q}, remainder 0")
            q, r = divide(q, c)
        print(f"  remainder {r}: multiplicity {count}")
        if count > 0:
            print(f"  {'odd: the graph crosses' if count % 2 == 1 else 'even: the graph touches'}")
    elif kind == "slant":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        q, r = divide([a, b, c], d)
        print(f"  divide [{a}, {b}, {c}] by x - ({d}): quotient {q}, remainder {r}")
        print(f"  slant asymptote y = ({q[0]})x + ({q[1]})")
    elif kind == "absval":
        a, b, c = nums[0], nums[1], nums[2]
        if c < 0:
            print(f"  an absolute value is never {c}: no solution")
        elif c == 0:
            print(f"  only 0 has absolute value 0: x = {Fraction(-b, a)}")
        else:
            print(f"  {a}x + ({b}) = {c} or {a}x + ({b}) = {-c}: x = {Fraction(c - b, a)} or x = {Fraction(-c - b, a)}")

problems = [
    ("Example 1 · through (1, 3) and (4, 9), at x = 10", "line", [1, 3, 4, 9, 10]),
    ("Example 2 · perpendicular to slope 2 through (4, 1)", "perp", [2, 1, 4, 1]),
    ("Example 7 · the multiplicity of 2 in x^3 - 3x^2 + 4", "multiplicity", [2, 1, -3, 0, 4]),
    ("Example 9 · (x^2 + 3x + 1)/(x - 1)", "slant", [1, 3, 1, 1]),
    ("Example 11 · |2x - 3| = 7", "absval", [2, -3, 7]),
    ("A horizontal line: perpendicular to slope 0 through (2, 5)", "perp", [0, 1, 2, 5]),
    ("Not a zero: 3 in x^3 - 3x^2 + 4", "multiplicity", [3, 1, -3, 0, 4]),
    ("No solution: |x + 1| = -2", "absval", [1, 1, -2]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

