from fractions import Fraction

def divide(coeffs, c):
    # synthetic division by x - c, coefficients highest power first: quotient, remainder
    q = []
    carry = 0
    for i in range(len(coeffs)):
        carry = carry * c + coeffs[i]
        if i < len(coeffs) - 1:
            q.append(carry)
    return q, carry

def solve(kind, nums):
    if kind == "line":
        x1, y1, x2, y2, x = nums[0], nums[1], nums[2], nums[3], nums[4]
        m = Fraction(y2 - y1, x2 - x1)
        b = y1 - m * x1
        return f"line: y = ({m})x + ({b}), at x = {x}, y = {m * x + b}"
    if kind == "perp":
        m, x0, y0 = Fraction(nums[0], nums[1]), nums[2], nums[3]
        if m == 0:
            return f"perp: x = {x0}"
        p = -1 / m
        return f"perp: y = ({p})x + ({y0 - p * x0})"
    if kind == "multiplicity":
        c, coeffs, count = nums[0], [], 0
        for k in range(1, len(nums)):
            coeffs.append(nums[k])
        q, r = divide(coeffs, c)
        while r == 0:
            count = count + 1
            q, r = divide(q, c)
        if count == 0:
            return f"multiplicity: c = {c}, not a zero"
        if count % 2 == 1:
            return f"multiplicity: c = {c}, multiplicity {count}, crosses"
        return f"multiplicity: c = {c}, multiplicity {count}, touches"
    if kind == "slant":
        q, r = divide([nums[0], nums[1], nums[2]], nums[3])
        return f"slant: y = ({q[0]})x + ({q[1]}), remainder {r}"
    a, b, c = nums[0], nums[1], nums[2]
    if c < 0:
        return "absval: no solution"
    if c == 0:
        return f"absval: x = {Fraction(-b, a)}"
    x1, x2 = Fraction(-c - b, a), Fraction(c - b, a)
    if x1 > x2:
        x1, x2 = x2, x1
    return f"absval: x = {x1} or x = {x2}"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

from fractions import Fraction

def solve(kind, nums):
    if kind == "plan":
        base, rate, budget = nums[0], nums[1], nums[2]
        return f"plan: C(u) = {base} + {rate}u, {budget} buys {Fraction(budget - base, rate)}"
    if kind == "top":
        a, b, c = nums[0], nums[1], nums[2]
        t = Fraction(-b, 2 * a)
        return f"top: t = {t}, height {a * t * t + b * t + c}"
    if kind == "pen":
        x = Fraction(nums[0], 4)
        return f"pen: {x} by {nums[0] - 2 * x}, area {x * (nums[0] - 2 * x)}"
    if kind == "tickets":
        P, S, L = nums[0], nums[1], nums[2]
        x = Fraction(S - L * P, 2 * L)
        return f"tickets: price {P + x}, sold {S - L * x}, revenue {(P + x) * (S - L * x)}"
    if kind == "buses":
        buses = -(-nums[0] // nums[1])
        return f"buses: {buses} buses, {buses * nums[1] - nums[0]} empty seats"
    income, total = nums[0], Fraction(0)
    limits, rates = [0, 10000, 40000], [10, 20, 30]
    for j in range(3):
        if income > limits[j]:
            top = income
            if j < 2 and limits[j + 1] < income:
                top = limits[j + 1]
            total = total + Fraction((top - limits[j]) * rates[j], 100)
    return f"tax: {total:.2f}, effective rate {100 * total / income:.2f}%"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

