from fractions import Fraction

def sign(v):
    if v > 0:
        return "+"
    return "-"

def line(a, b):
    # the text of ax + b, as you'd write it by hand
    if a == 0:
        return f"{b}"
    s = f"{a}x"
    if a == 1:
        s = "x"
    if a == -1:
        s = "-x"
    if b > 0:
        return s + f" + {b}"
    if b < 0:
        return s + f" - {-b}"
    return s

def p(a, zeros, x):
    # a times (x - r)^m for each (zero, multiplicity) pair, as in Polynomial Functions
    total = a
    for r, m in zeros:
        total = total * (x - r) ** m
    return total

def solve(kind, nums):
    if kind == "sketch" or kind == "inverse":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        print(f"  ({line(a, b)})/({line(c, d)}): ad - bc = {a * d - b * c}")
        if a * d - b * c == 0:
            print(f"  the top is a multiple of the bottom: the constant {Fraction(a, c)}, hole at x = {Fraction(-d, c)}")
        elif kind == "sketch":
            print(f"  vertical asymptote x = {Fraction(-d, c)}, horizontal asymptote y = {Fraction(a, c)}")
            print(f"  x-intercept {Fraction(-b, a) if a != 0 else 'none'}, y-intercept {Fraction(b, d) if d != 0 else 'none'}")
        else:
            print(f"  y(cx + d) = ax + b gives x(cy - a) = b - dy, so the inverse is ({line(-d, b)})/({line(c, -a)})")
            y = Fraction(a * 5 + b, c * 5 + d)
            print(f"  check: f(5) = {y}, and the inverse sends it to {(-d * y + b) / (c * y - a)}")
    elif kind == "signchart":
        a, zeros, degree = nums[0], [], 0
        for k in range(1, len(nums), 2):
            zeros.append((nums[k], nums[k + 1]))
            degree = degree + nums[k + 1]
        tests = [zeros[0][0] - 1]
        for k in range(len(zeros) - 1):
            tests.append(Fraction(zeros[k][0] + zeros[k + 1][0], 2))
        tests.append(zeros[len(zeros) - 1][0] + 1)
        print(f"  degree {degree}, leading coefficient {a}: far left {sign(p(a, zeros, -1000))}, far right {sign(p(a, zeros, 1000))}")
        for t in tests:
            print(f"  test x = {t}: p = {p(a, zeros, t)}, {sign(p(a, zeros, t))}")
    elif kind == "wallpen":
        L, W = nums[0], nums[1]
        x = Fraction(L, 4)
        print(f"  the vertex x = {L}/4 = {x} needs a far side of {L - 2 * x}")
        if L - 2 * x > W:
            x = Fraction(L - W, 2)
            print(f"  that's longer than the {W} m wall, so the far side is {W} and x = {x}")
        print(f"  area {x} * {L - 2 * x} = {x * (L - 2 * x)}")

problems = [
    ("Example 3 · sketch (2x + 1)/(x - 3)", "sketch", [2, 1, 1, -3]),
    ("Example 3 · invert (2x + 1)/(x - 3)", "inverse", [2, 1, 1, -3]),
    ("Example 2 · -x(x - 2)^2(x + 1)", "signchart", [-1, -1, 1, 0, 1, 2, 2]),
    ("Example 5 · 80 m of fence, a 30 m wall", "wallpen", [80, 30]),
    ("A constant in disguise: (2x - 4)/(x - 2)", "sketch", [2, -4, 1, -2]),
    ("No x-intercept: 4/(x + 2)", "sketch", [0, 4, 1, 2]),
    ("A wall long enough: 60 m of fence, a 40 m wall", "wallpen", [60, 40]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

