from fractions import Fraction

def sign(v):
    if v > 0:
        return "+"
    return "-"

def line(a, b):
    # the text of ax + b, as you'd write it by hand
    if a == 0:
        return f"{b}"
    s = f"{a}x"
    if a == 1:
        s = "x"
    if a == -1:
        s = "-x"
    if b > 0:
        return s + f" + {b}"
    if b < 0:
        return s + f" - {-b}"
    return s

def p(a, zeros, x):
    # a times (x - r)^m for each (zero, multiplicity) pair, as in Polynomial Functions
    total = a
    for r, m in zeros:
        total = total * (x - r) ** m
    return total

def solve(kind, nums):
    if kind == "sketch" or kind == "inverse":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        if a * d - b * c == 0 and kind == "sketch":
            return f"sketch: constant {Fraction(a, c)}, hole at x = {Fraction(-d, c)}"
        if a * d - b * c == 0:
            return "inverse: none, f is constant"
        if kind == "inverse":
            return f"inverse: ({line(-d, b)})/({line(c, -a)})"
        x_int = Fraction(-b, a) if a != 0 else "none"
        y_int = Fraction(b, d) if d != 0 else "none"
        return f"sketch: VA x = {Fraction(-d, c)}, HA y = {Fraction(a, c)}, x-int {x_int}, y-int {y_int}"
    if kind == "signchart":
        a, zeros = nums[0], []
        for k in range(1, len(nums), 2):
            zeros.append((nums[k], nums[k + 1]))
        signs = sign(p(a, zeros, zeros[0][0] - 1))
        for k in range(len(zeros) - 1):
            signs = signs + " " + sign(p(a, zeros, Fraction(zeros[k][0] + zeros[k + 1][0], 2)))
        signs = signs + " " + sign(p(a, zeros, zeros[len(zeros) - 1][0] + 1))
        return f"signchart: left {sign(p(a, zeros, -1000))}, right {sign(p(a, zeros, 1000))}, signs {signs}"
    L, W = nums[0], nums[1]
    x = Fraction(L, 4)
    if L - 2 * x > W:
        x = Fraction(L - W, 2)
    return f"wallpen: x = {x}, far side {L - 2 * x}, area {x * (L - 2 * x)}"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))
